### Code Implementation Example

```ts
import { test, expect } from '@config/base-test';
import { getPreferredNavLabel } from '../smoke-helpers';

test.describe('E2E-CART-011 – Validate cart behavior during size button blockage scenarios', () => {
  let initialCartCount: number;

  test.beforeAll(async ({ page, ecommercePLPPage, ecommercePDPPage }) => {
    test.setTimeout(90000); // Extended timeout to handle staging quirks
    await page.setViewportSize({ width: 1920, height: 1080 }); // Match test viewport

    const navLabel = getPreferredNavLabel({ name: 'Dr. Martens NZ' }, false); // WOMEN fallback logic
    await ecommercePLPPage.navigateToPlp(page, navLabel);
  });

  test('Add product to cart despite L3L4 navigation blocking size selection', async ({ ecommercePDPPage, ecommerceCartOverlayPage }) => {
    initialCartCount = await ecommerceCartOverlayPage.getMiniCartCount();

    // Select size
    const sizeButtonSelector = ecommercePDPPage.sizeButtonSelector;
    const isTopmost = await page.locator(sizeButtonSelector).evaluate((el) => {
      const rect = el.getBoundingClientRect();
      const hit = document.elementFromPoint(rect.left + rect.width / 2, rect.top + rect.height / 2);
      return hit === el || el.contains(hit);
    });

    if (!isTopmost) {
      await page.locator(sizeButtonSelector).evaluate((el) =>
        el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, composed: true }))
      );
    } else {
      await page.locator(sizeButtonSelector).click();
    }

    // Validate size registration
    expect(await ecommercePDPPage.isSizeSelected()).toBeTruthy();

    // Add to cart
    await ecommercePDPPage.addToCart();
    await ecommerceCartOverlayPage.waitForMiniCartCountIncrement(initialCartCount);
  });

  test.afterEach(async ({ ecommerceCartOverlayPage }) => {
    await ecommerceCartOverlayPage.clearCart();
  });
});
```

